    try {
        return findNativeImpl(target);
    } catch (NullPointerException e) {
        System.err.println("Target URL cannot be null.");
        return null;
    } catch (IllegalArgumentException e) {
        System.err.println("Target URL is invalid or cannot be processed.");
        return null;
    }
}

